insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('fastbill','buchhaltung','FastBill','{"id":1,"name":"FastBill","slug":"fastbill","category":"Buchhaltung","categorySlug":"buchhaltung","fit":"Selbstständige und kleine Dienstleistungsunternehmen mit Schwerpunkt Angebot, Rechnung, Beleg und Steuerberaterübergabe.","pricing":"Solo 10 €/Monat bei monatlicher Zahlung oder 9 €/Monat bei jährlicher Zahlung; Plus 15/14 €, Pro 30/27 €, Premium ab 59/53 €; netto. Add-ons kosten extra.","features":"E-Rechnungen, Mahnwesen, Belege, Banking, DATEV-Export, UStVA; wiederkehrende Rechnungen erst ab Pro, automatische Belegverarbeitung vor allem Premium.","review":"Die Tarifstaffel lässt kleine Betriebe günstig mit dem Rechnungskern beginnen. Wer viele Personen, automatische Abläufe oder Belegverarbeitung braucht, muss die höherpreisigen Pakete und Zusatzmodule mitrechnen. FastBill beschreibt die Zusammenarbeit mit der Steuerberatung ausdrücklich; für komplexe Abschlüsse sollte die konkrete Arbeitsteilung vor Auswahl geklärt werden.","alternatives":["Lexware Office für breitere Buchhaltung","Billomat für dokumentenlastige Abläufe."],"sources":[{"label":"Preisquelle","url":"https://www.fastbill.com/preise"},{"label":"Funktionen","url":"https://www.fastbill.com/funktionen"}],"vendorUrl":"https://www.fastbill.com/preise","priceShort":"Solo 10 €/Monat bei monatlicher Zahlung oder 9 €/Monat bei jährlicher Zahlung"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'fastbill','https://www.fastbill.com/preise','direct',true where not exists (select 1 from public.outbound_links where product_slug='fastbill' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('lexware-office','buchhaltung','Lexware Office','{"id":2,"name":"Lexware Office","slug":"lexware-office","category":"Buchhaltung","categorySlug":"buchhaltung","fit":"Gründer, Freiberufler und kleine Unternehmen, die Belege, Rechnungen und laufende Buchhaltung in einem System verbinden wollen.","pricing":"S 7,90 €, M 12,90 €, L 21,90 €, XL 32,90 € pro Monat, zzgl. MwSt.; Aktionspreise nicht als Regelpreis verwenden.","features":"Belege ab S, Ausgangsrechnungen ab M, EÜR und UStVA ab L; XL ergänzt unter anderem API und besondere Rechnungstypen.","review":"Die klare Staffelung ist hilfreich, wenn der Betrieb von reiner Belegablage zur eigenen Buchführung wächst. Ein „ab 7,90 €“-Vergleich wäre irreführend für Unternehmen, die tatsächlich Rechnungen oder EÜR benötigen: dafür gelten M beziehungsweise L. Prüfen Sie vor der Entscheidung die benötigte Version und Zusatzkosten für Lohn.","alternatives":["sevdesk","Sage Active."],"sources":[{"label":"Preise und Versionen","url":"https://www.lexware.de/preise/"},{"label":"Produkt","url":"https://www.lexware.de/buchhaltungssoftware/"}],"vendorUrl":"https://www.lexware.de/preise/","priceShort":"S 7,90 €, M 12,90 €, L 21,90 €, XL 32,90 € pro Monat, zzgl"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
