insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('sevdesk','buchhaltung','sevdesk','{"id":3,"name":"sevdesk","slug":"sevdesk","category":"Buchhaltung","categorySlug":"buchhaltung","fit":"Selbstständige und kleine Unternehmen, die Rechnungen und Buchhaltung webbasiert organisieren.","pricing":"Rechnung 12,90 €, Buchhaltung 25,90 €, Buchhaltung Pro 34,90 € pro Monat bei 24 Monaten Laufzeit, zzgl. MwSt.; Aktionsrabatte gelten befristet. Andere Laufzeiten können abweichen.","features":"E-Rechnungen, Belege, Bankabgleich, Steuerberater-Zusammenarbeit und je nach Tarif erweiterte Buchhaltung.","review":"Die Trennung zwischen Rechnungs- und Buchhaltungstarif macht den Einstieg verständlich. Wer Buchführung, Auswertungen oder Teamfunktionen braucht, sollte den passenden Tarif anhand der Vergleichstabelle prüfen; ein reiner Einstiegspreis reicht hier nicht. Die öffentlich sichtbaren Preise können durch Aktionen und Abrechnungsmodus abweichen.","alternatives":["Lexware Office","FastBill."],"sources":[{"label":"Preise","url":"https://sevdesk.de/preise/"},{"label":"Produktübersicht","url":"https://sevdesk.de/produktuebersicht/"}],"vendorUrl":"https://sevdesk.de/preise/","priceShort":"Rechnung ab 12,90 €, Buchhaltung ab 25,90 €, Buchhaltung Pro ab 34,90 € pro Monat laut aktueller Herstell"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'sevdesk','https://sevdesk.de/preise/','direct',true where not exists (select 1 from public.outbound_links where product_slug='sevdesk' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('sage-active','buchhaltung','Sage Active','{"id":4,"name":"Sage Active","slug":"sage-active","category":"Buchhaltung","categorySlug":"buchhaltung","fit":"Kleine Unternehmen mit Geschäftskunden, die Angebote und Rechnungen digital abwickeln und die Buchhaltung samt Lohn für wenige Beschäftigte selbst in einer Cloudlösung erledigen möchten.","pricing":"Starter 25 € und Essentials 49 € pro Monat, jeweils zzgl. MwSt. und monatlich kündbar. Starter enthält 5 Nutzer und 300 Rechnungen pro Monat, Essentials 10 Nutzer, 500 Rechnungen und 2 Beschäftigte für Lohn und HR. Jede weitere Person in der Lohnabrechnung kostet 3 € pro Monat, zusätzliche Rechnungspakete beginnen bei 10 € für 100 Rechnungen. Eine Neukundenaktion mit 50 % Rabatt für drei Monate gilt laut Hersteller bis 30. September 2026.","features":"Starter: Angebote, Aufträge, Lieferscheine und Rechnungen, Belegerfassung mit künstlicher Intelligenz, Einlesen von XRechnung und ZUGFeRD, Bankabgleich, Umsatzberichte, Zugang für externe Buchhalter, offene API und mobile App. Essentials ergänzt doppelte Buchführung mit SKR03 und SKR04, Anlagenbuchhaltung, automatische Buchungssätze, GuV und Bilanz in Echtzeit, einen Bericht zur Einnahmenüberschussrechnung, die Umsatzsteuervoranmeldung über ELSTER, die Vorbereitung des Jahresabschlusses, den Export im DATEV Format sowie Lohnabrechnung mit Meldungen und Mitarbeiterportal.","review":"Sage Active ist eine der wenigen Cloudlösungen für kleine Betriebe, die Auftragsbearbeitung, doppelte Buchführung und Lohnabrechnung unter einem Vertrag bündeln. Für einen fairen Vergleich zählt fast immer Essentials: Starter deckt Angebote, Rechnungen und Zahlungsabgleich ab, überlässt die Buchführung aber ausdrücklich externen Buchhaltern. Die Kontingente sind großzügig bemessen, doch Rechnungspakete und jede weitere Person in der Lohnabrechnung kosten extra. Beim Versand elektronischer Rechnungen verweist Sage derzeit auf eine kommende Funktion; der Empfang von XRechnung und ZUGFeRD ist bereits enthalten. Die Jahressteuererklärung und die E-Bilanz erledigt Sage Active nicht selbst.","alternatives":["Lexware Office für günstigere Einstiegstarife mit Einnahmenüberschussrechnung","sevdesk für Rechnung und Buchhaltung ohne integrierte Lohnabrechnung"],"sources":[{"label":"Produktseite mit Paketen, Kontingenten, Zusatzkosten und FAQ","url":"https://www.sage.com/de-de/produkte/sage-active/"}],"vendorUrl":"https://www.sage.com/de-de/produkte/sage-active/","priceShort":"Starter 25 €, Essentials 49 € pro Monat zzgl. MwSt."}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'sage-active','https://www.sage.com/de-de/produkte/sage-active/','direct',true where not exists (select 1 from public.outbound_links where product_slug='sage-active' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('billomat','buchhaltung','Billomat','{"id":5,"name":"Billomat","slug":"billomat","category":"Buchhaltung","categorySlug":"buchhaltung","fit":"Freiberufler, kleine Teams und wachsende Handels-/Dienstleistungsbetriebe mit vielen Dokumenten.","pricing":"Professional ab 29 €/Monat monatlich bzw. 19 €/Monat jährlich, Business ab 39/29 €, Enterprise ab 119/99 €; netto.","features":"Rechnungen, E-Rechnung, Belege, EÜR, Mahnungen, Angebote; DATEVconnect und Banking-Verknüpfung laut Tariftabelle erst ab Business. Professional umfasst einen Nutzer und 30 Rechnungen pro Monat.","review":"Die Funktionsliste ist breit, doch die Grenzen des kleinsten Tarifs sind für Teams entscheidend. Ein Betrieb mit mehreren Nutzern oder größerem Rechnungsvolumen sollte Business als realistischen Vergleichspunkt nehmen. API-Nutzung und zusätzliche Personen können die Kosten erhöhen.","alternatives":["FastBill für fakturazentrierte Arbeit","Lexware Office für Buchhaltung."],"sources":[{"label":"Preise und Tarifdetails","url":"https://www.billomat.com/preise/"}],"vendorUrl":"https://www.billomat.com/preise/","priceShort":"Professional ab 29 €/Monat monatlich bzw"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'billomat','https://www.billomat.com/preise/','direct',true where not exists (select 1 from public.outbound_links where product_slug='billomat' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('sage-payroll','lohnabrechnung','Sage Payroll (Sage Lohnabrechnung)','{"id":6,"name":"Sage Payroll (Sage Lohnabrechnung)","slug":"sage-payroll","category":"Lohnabrechnung","categorySlug":"lohnabrechnung","fit":"Kleine Arbeitgeber mit bis zu 150 Beschäftigten und üblichen Lohnfällen, die die Entgeltabrechnung selbst in der Cloud erledigen und je nach Bedarf Personalfunktionen hinzunehmen möchten.","pricing":"Payroll Essentials 20 €, Standard 30 € und Premium 40 € pro Monat, jeweils inklusive 5 Beschäftigter und zzgl. MwSt. Jede weitere Person kostet 3 €, 5 € beziehungsweise 7 € pro Monat; bis zu 150 Beschäftigte sind möglich. Laut Hersteller gibt es keine langfristige Bindung, Upgrade und Kündigung sind jederzeit möglich. Eine ältere Sage Preisseite nennt noch 6,50 € beziehungsweise 8,50 € je Beschäftigtem; maßgeblich ist die aktuelle Paketübersicht auf der Produktseite.","features":"Alle Pakete: automatisierte Lohnabrechnung mit gesetzlichen Meldungen einschließlich Sofortmeldungen, Zugang der Beschäftigten zu Abrechnungen und Steuerdokumenten, mobile App, bis zu drei Abwesenheitsarten, Mitarbeiterdokumente, Rechteverwaltung, mehrere Firmen und Buchhaltungsexport für Sage und DATEV. Standard ergänzt ein Portal für das Onboarding, Arbeitszeiten und Überstunden, Genehmigungsabläufe, Organigramm sowie Urlaub und Abwesenheiten. Premium bringt zusätzlich Schichtplanung und Spesen per App. Recruiting und Performance sind ab Standard zubuchbar. Baulohn, Betriebsrenten und öffentlicher Dienst sind ausgeschlossen.","review":"Sage Payroll ist ein schlanker Weg, die Lohnabrechnung aus dem Lohnbüro in den eigenen Betrieb zu holen. Das neue Paketmodell mit fünf enthaltenen Beschäftigten macht sehr kleine Teams günstig; ab etwa zehn Personen bestimmt der Aufpreis je Kopf die Rechnung. Der Unterschied zwischen den Paketen liegt fast vollständig in den Personalfunktionen, nicht in der Lohnabrechnung selbst. Wer nur abrechnen möchte, fährt mit Essentials. Die Ausschlussliste ist eindeutig: Baubetriebe, Betriebsrenten und öffentlicher Dienst brauchen eine andere Lösung.","alternatives":["Lexware Office Lohn & Gehalt bei bestehender Lexware Buchhaltung","Agenda Personalwesen für Baulohn und komplexere Lohnfälle"],"sources":[{"label":"Produktseite mit aktuellen Paketen, Preisen und Ausschlüssen","url":"https://www.sage.com/de-de/sage-business-cloud/lohnabrechnung/"},{"label":"Ältere Preisseite mit Preisen je Beschäftigtem","url":"https://www.sage.com/de-de/sage-business-cloud/lohnabrechnung/preis/"}],"vendorUrl":"https://www.sage.com/de-de/sage-business-cloud/lohnabrechnung/","priceShort":"ab 20 € pro Monat für 5 Beschäftigte"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'sage-payroll','https://www.sage.com/de-de/sage-business-cloud/lohnabrechnung/','direct',true where not exists (select 1 from public.outbound_links where product_slug='sage-payroll' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('lexware-office-lohn-gehalt','lohnabrechnung','Lexware Office Lohn & Gehalt','{"id":7,"name":"Lexware Office Lohn & Gehalt","slug":"lexware-office-lohn-gehalt","category":"Lohnabrechnung","categorySlug":"lohnabrechnung","fit":"Kleinbetriebe, besonders wenn Lexware Office bereits für die Buchhaltung genutzt wird.","pricing":"ab 12,90 € pro Monat zzgl. MwSt. laut Preisübersicht; der Hersteller nennt die Abrechnung nach Mitarbeitenden, daher konkrete Staffel im Checkout prüfen.","features":"geführte Abrechnung, Meldungen an Finanzamt und Sozialversicherung sowie automatische Buchung der Personalkosten in Lexware Office.","review":"Die enge Verbindung mit der Buchhaltung vermeidet manuelle Übergaben. Der Hersteller nennt aber ausdrücklich ausgeschlossene Beschäftigungsarten und Entgeltfälle, darunter Baulohn und öffentlichen Dienst. Solche Anforderungen vor der Auswahl mit der aktuellen Ausschlussliste abgleichen.","alternatives":["Sage Payroll bei einfacher Lohnabrechnung","DATEV bei komplexeren Fällen."],"sources":[{"label":"Preise und Ausschlüsse","url":"https://www.lexware.de/preise/"},{"label":"Produkt","url":"https://www.lexware.de/lohnprogramm-lohnsoftware/"}],"vendorUrl":"https://www.lexware.de/preise/","priceShort":"ab 12,90 € pro Monat zzgl"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'lexware-office-lohn-gehalt','https://www.lexware.de/preise/','direct',true where not exists (select 1 from public.outbound_links where product_slug='lexware-office-lohn-gehalt' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('datev-lohn-und-gehalt','lohnabrechnung','DATEV Lohn und Gehalt classic','{"id":8,"name":"DATEV Lohn und Gehalt classic","slug":"datev-lohn-und-gehalt","category":"Lohnabrechnung","categorySlug":"lohnabrechnung","fit":"Betriebe und Fachkräfte, die umfangreiche deutsche Lohnfälle verarbeiten und bereits mit DATEV arbeiten.","pricing":"Die Produktseite zeigt „ab 15,86 €/Monat“; eine DATEV-Preisliste für 2026 unterscheidet Lizenzarten und nennt für eine Einer-Netzlizenz 27,20 €/Monat. Deshalb keinen dieser Beträge als vollständigen Gesamtpreis darstellen; Lizenz, Rechenzentrumsnutzung und Zusatzdienste einzeln prüfen.","features":"unbegrenzt abrechenbare Arbeitnehmer, Baulohn und weitere Sonderfälle, Meldung über DATEV-Rechenzentrum, lokale PC-Verarbeitung.","review":"Der fachliche Umfang ist ein starkes Argument bei komplexer Entgeltabrechnung. Die lokale DATEV-Systemumgebung und mehrteilige Preisstruktur verlangen mehr Planung als ein einfacher Cloud-Einstieg.","alternatives":["Agenda Personalwesen","Sage Payroll."],"sources":[{"label":"Produkt und Preise","url":"https://www.datev.de/web/de/shop/produkt-details/41842"},{"label":"DATEV-Preisliste","url":"https://www.datev.de/content/dam/markenassets/preislisten/DATEV-Preisliste_geaenderte_preise_ab_2025_lfu.pdf"}],"vendorUrl":"https://www.datev.de/web/de/shop/produkt-details/41842","priceShort":"Die Produktseite zeigt „ab 15,86 €/Monat“"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
