insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('agenda-personalwesen','lohnabrechnung','Agenda Personalwesen','{"id":9,"name":"Agenda Personalwesen","slug":"agenda-personalwesen","category":"Lohnabrechnung","categorySlug":"lohnabrechnung","fit":"Kleine bis mittelgroße Betriebe mit intern verantworteter Lohnabrechnung und Bedarf an optionalen Personalmodulen.","pricing":"Personalwesen-Komplettsystem ab 50 €/Monat; die Produktseite zeigt Paketbestandteile mit Grundpreisen und nutzungsabhängigen Kosten pro Mitarbeitendem. Endpreis abhängig von Arbeitsplätzen, Modulen und Abrechnungsvolumen; 12 Monate Mindestlaufzeit laut Hersteller.","features":"Lohn und Gehalt, Meldewesen, Mitarbeiterportal, digitale Akte, Urlaubsverwaltung; Baulohn optional.","review":"Agenda eignet sich als prüfenswerte Fachlösung, wenn spezielle Lohnprozesse und Experten-Support wichtig sind. Ein Vergleich nur der Grundgebühr wäre zu niedrig; die variable Komponente und die Vertragsdauer gehören in die Gesamtkostenrechnung.","alternatives":["DATEV Lohn und Gehalt","Sage Payroll."],"sources":[{"label":"Preismodell","url":"https://www.agenda-software.de/unternehmen/preise.php"},{"label":"Leistungen und Paketpreise","url":"https://www.agenda-software.de/unternehmen/personalwesen.php"}],"vendorUrl":"https://www.agenda-software.de/unternehmen/preise.php","priceShort":"Personalwesen-Komplettsystem ab 50 €/Monat"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
