insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('personio-payroll','lohnabrechnung','Personio Payroll','{"id":10,"name":"Personio Payroll","slug":"personio-payroll","category":"Lohnabrechnung","categorySlug":"lohnabrechnung","fit":"Wachsende Unternehmen, die Stammdaten und Lohnlauf in derselben HR-Umgebung verbinden wollen.","pricing":"Individuelles Angebot; Personio veröffentlicht für das HR-System keine feste deutsche Monatsgebühr und beschreibt Mitarbeiterzahl und Apps als Preisfaktoren.","features":"Payroll als Teil der Personio-Plattform; laut Hersteller Zusammenarbeit mit Steuerberatung oder eigener Abrechnung möglich.","review":"Sinnvoll vor allem, wenn Personio als HR-Kernsystem eingesetzt oder ernsthaft geplant wird. Für eine isolierte, sehr kleine Lohnabrechnung ist vorab zu prüfen, ob Einführung, Konfiguration und Gesamtkosten zum Bedarf passen. Payroll-Angebot und enthaltene HR-Module sollten schriftlich abgegrenzt werden.","alternatives":["Sage Payroll","Lexware Office Lohn & Gehalt."],"sources":[{"label":"Payroll","url":"https://www.personio.de/funktionen/personio-payroll/"},{"label":"Preismodell","url":"https://www.personio.de/preise/"}],"vendorUrl":"https://www.personio.de/funktionen/personio-payroll/","priceShort":"Individuelles Angebot"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
