insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('personio','hr','Personio','{"id":11,"name":"Personio","slug":"personio","category":"Personal","categorySlug":"hr","fit":"Unternehmen ab etwa zehn Mitarbeitenden, die Personalstammdaten, Zeit und Prozesse zentralisieren möchten.","pricing":"Auf Anfrage; abhängig von Beschäftigtenzahl und zusätzlichen Apps.","features":"Core mit Profilen, Dokumenten, Berichten, Workflows, Zeit und vorbereitender Lohnbuchhaltung; Core Pro erweitert unter anderem API und Rechte.","review":"Die Breite der Plattform kann Medienbrüche im HR-Alltag reduzieren. Entscheidend ist, welche gewünschten Funktionen bereits in Core liegen und welche als App oder Pro-Funktion hinzukommen. Auch Einführungsaufwand und Payroll sollten separat abgefragt werden.","alternatives":["Factorial für modularen Einstieg","HR WORKS für DACH-orientierte Prozesse."],"sources":[{"label":"Pakete und Preislogik","url":"https://www.personio.de/preise/"}],"vendorUrl":"https://www.personio.de/preise/","priceShort":"Auf Anfrage"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
