insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('factorial','hr','Factorial','{"id":12,"name":"Factorial","slug":"factorial","category":"Personal","categorySlug":"hr","fit":"Kleine und mittlere Unternehmen, die HR, Zeit, Talent und gegebenenfalls Finanzen modular verbinden wollen.","pricing":"Hersteller nennt Einstieg ab 8 € pro Nutzer und Monat; konkretes Angebot hängt von ausgewählten Modulen ab.","features":"Core umfasst Mitarbeiterverzeichnis, On-/Offboarding-Vorlagen, Signatur und Benachrichtigungen; weitere Zeit-, Talent- und Finanzfunktionen auswählbar.","review":"Das modulare Konzept ist gut, wenn ein Unternehmen schrittweise digitalisiert. Für einen fairen Vergleich müssen die gewünschten Module und die Zahl der abrechenbaren Nutzer schriftlich feststehen; „ab 8 €“ ist kein Preis für jede gezeigte Funktion.","alternatives":["Kenjo bei Schicht- und Zeitfokus","Personio bei breiter HR-Plattform."],"sources":[{"label":"Preise und Module","url":"https://factorialhr.de/preise"}],"vendorUrl":"https://factorialhr.de/preise","priceShort":"Hersteller nennt Einstieg ab 8 € pro Nutzer und Monat"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'factorial','https://factorialhr.de/preise','direct',true where not exists (select 1 from public.outbound_links where product_slug='factorial' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('kenjo','hr','Kenjo','{"id":13,"name":"Kenjo","slug":"kenjo","category":"Personal","categorySlug":"hr","fit":"Betriebe mit Schichten, Zeit- und Abwesenheitsprozessen sowie digitaler Personalakte.","pricing":"Aktuelle Preisseite rendert in der Textansicht widersprüchliche „0,0 €“-Werte; kein verifizierter deutscher Listenpreis. Individuelles Angebot einholen; Onboarding kann einmalig berechnet werden.","features":"Starter mit Zeit, Urlaub, Dokumenten und Schichtplanung; Growth ergänzt Workflows, Signatur, Berechtigungen und Auswertungen; Connect bietet unter anderem API und fortgeschrittene Integrationen. Recruiting ist Zusatzmodul.","review":"Für operative Teams sind Schicht- und Zeitfunktionen relevanter als eine allgemeine HR-Vollständigkeitsbehauptung. Vor dem Vergleich den konkreten Plan, Recruiting-Add-on und Onboardingkosten prüfen.","alternatives":["HR WORKS","Factorial."],"sources":[{"label":"Tarife und Funktionen","url":"https://www.kenjo.io/de/preise"}],"vendorUrl":"https://www.kenjo.io/de/preise","priceShort":"Aktuelle Preisseite rendert in der Textansicht widersprüchliche „0,0 €“-Werte"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'kenjo','https://www.kenjo.io/de/preise','direct',true where not exists (select 1 from public.outbound_links where product_slug='kenjo' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('hr-works','hr','HR WORKS','{"id":14,"name":"HR WORKS","slug":"hr-works","category":"Personal","categorySlug":"hr","fit":"Mittelständische Unternehmen mit Personalverwaltung, Zeitwirtschaft und Reisekosten in einem System.","pricing":"Kein verifizierter Listenbetrag auf Herstellerseite; monatliche Gebühr setzt sich laut FAQ aus Lizenzzahl plus Grundgebühr zusammen.","features":"Personalverwaltung, Zeiterfassung, Abwesenheiten, Reisekosten und vorbereitende Lohnbuchhaltung.","review":"Der stärkste Grund zur Prüfung ist die Verbindung von HR und Reisekosten, besonders in deutschen Betrieben mit häufigen Dienstreisen. Es ist wichtig, vorbereitende Lohnbuchhaltung nicht als vollständig integrierte Entgeltabrechnung zu missverstehen; den gewünschten Ablauf und Schnittstellen im Angebot bestätigen lassen.","alternatives":["Personio","Kenjo."],"sources":[{"label":"Produkt","url":"https://www.hrworks.de/produkt/personalverwaltung-software/"},{"label":"Abrechnungsmodell","url":"https://www.hrworks.de/produkt/faq-haeufig-gestellte-fragen-antworten/"}],"vendorUrl":"https://www.hrworks.de/produkt/personalverwaltung-software/","priceShort":"Kein verifizierter Listenbetrag auf Herstellerseite"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'hr-works','https://www.hrworks.de/produkt/personalverwaltung-software/','direct',true where not exists (select 1 from public.outbound_links where product_slug='hr-works' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('hibob-bob','hr','HiBob / Bob','{"id":15,"name":"HiBob / Bob","slug":"hibob-bob","category":"Personal","categorySlug":"hr","fit":"Wachsende, teils international aufgestellte Mittelständler mit komplexeren HR-Prozessen.","pricing":"Individuelles Angebot nach Mitarbeiterzahl und Modulen.","features":"Core mit Mitarbeiterdaten, Dokumenten, Abwesenheiten, Workflows, Integrationen und Analysen; weitere Module nach Auswahl.","review":"Bob kann interessant sein, wenn HR-Reporting und mehrere Teams oder Länder zusammenkommen. Ein kleines Unternehmen mit einfachen Zeit- und Aktenprozessen sollte die Einführung und die Modulpreise gegen schlankere Alternativen halten. Payroll-Integration nicht mit einer für Deutschland bestätigten nativen Lohnabrechnung gleichsetzen.","alternatives":["Personio","Factorial."],"sources":[{"label":"Tarife und Preismodell","url":"https://www.hibob.com/de/pricing-plans/"},{"label":"Payroll-Einordnung","url":"https://www.hibob.com/de/faq/"}],"vendorUrl":"https://www.hibob.com/de/pricing-plans/","priceShort":"Individuelles Angebot nach Mitarbeiterzahl und Modulen"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'hibob-bob','https://www.hibob.com/de/pricing-plans/','direct',true where not exists (select 1 from public.outbound_links where product_slug='hibob-bob' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('pipedrive','crm','Pipedrive','{"id":16,"name":"Pipedrive","slug":"pipedrive","category":"CRM","categorySlug":"crm","fit":"Vertriebsteams, die eine visuelle Pipeline und konsequente Nachverfolgung von Deals benötigen.","pricing":"Kein verifizierter Euro-Listenpreis auf der deutschen Preisseite. Lite, Growth, Premium und Ultimate sind dort auswählbar; lassen Sie sich den für Deutschland gültigen Europreis je Nutzer, Zahlungsweise und Zusatzfunktion schriftlich bestätigen.","features":"Leads, Deals, Kontakte, Kalender, Berichte; höhere Pläne und Add-ons ergänzen Automatisierung.","review":"Die klare Konzentration auf den Vertrieb macht Pipedrive für kleine Sales-Teams gut prüfbar. Unternehmen, die Marketing, Support und tiefe Anpassungen in einer Suite erwarten, sollten Funktionsumfang und Zusatzkosten gegen HubSpot oder SuperOffice halten.","alternatives":["CentralStationCRM für sehr kleine Teams","HubSpot Sales Hub für Plattformausbau."],"sources":[{"label":"Deutsche Preis- und Funktionsseite","url":"https://www.pipedrive.com/de/pricing"}],"vendorUrl":"https://www.pipedrive.com/de/pricing","priceShort":"Deutsche Preisseite zeigte Lite ab 14 US-Dollar pro Nutzer und Monat bei Jahreszahlung"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'pipedrive','https://www.pipedrive.com/de/pricing','direct',true where not exists (select 1 from public.outbound_links where product_slug='pipedrive' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('hubspot-sales-hub','crm','HubSpot Sales Hub','{"id":17,"name":"HubSpot Sales Hub","slug":"hubspot-sales-hub","category":"CRM","categorySlug":"crm","fit":"Teams, die CRM und Vertrieb mit späterem Marketing-/Service-Ausbau verbinden möchten.","pricing":"Aktuelle dynamische DE-Preisseite zeigt Starter ab 7 €/Lizenz und Monat, Professional 90 €, Enterprise 150 €; Abrechnungsart, mögliche Aktionen und Onboarding im Checkout bestätigen.","features":"Kontakte und Deals, E-Mail, Meetingplanung; höhere Stufen bieten mehr Pipelines, Automatisierung und Steuerung.","review":"Der kostenlose Einstieg und das breite Ökosystem senken die Startschwelle. Für wachsende Teams können Lizenzstufen und kostenpflichtige Zusatzprodukte einen großen Kostensprung bedeuten; der Vergleich muss den tatsächlich benötigten Workflow abbilden.","alternatives":["Pipedrive für fokussierten Vertrieb","Zoho CRM für anpassbare Prozesse."],"sources":[{"label":"Aktuelle Preisseite","url":"https://www.hubspot.de/pricing/sales"},{"label":"Produkt","url":"https://www.hubspot.de/products/sales"}],"vendorUrl":"https://www.hubspot.de/pricing/sales","priceShort":"Aktuelle dynamische DE-Preisseite zeigt Starter ab 7 €/Lizenz und Monat, Professional 90 €, Enterprise 15"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'hubspot-sales-hub','https://www.hubspot.de/pricing/sales','direct',true where not exists (select 1 from public.outbound_links where product_slug='hubspot-sales-hub' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('centralstationcrm','crm','CentralStationCRM','{"id":18,"name":"CentralStationCRM","slug":"centralstationcrm","category":"CRM","categorySlug":"crm","fit":"Kleine deutsche Teams, die Kontakte und Aktivitäten ohne komplexe CRM-Einführung teilen möchten.","pricing":"Starter kostenlos (bis 3 Nutzer, 200 Kontakte); Team 24 €/Monat (3 Nutzer, 3.000 Kontakte), Small Office 75 € (10 Nutzer), Business 149 € (20 Nutzer), Enterprise 289 € (40 Nutzer); zzgl. MwSt.","features":"Gleicher Grundfunktionsumfang über Pakete, Grenzen liegen vor allem bei Nutzern, Kontakten und Speicher.","review":"Diese Preislogik ist für kleine Teams leicht zu verstehen und verhindert Funktionsrätsel zwischen Stufen. Wachsende Kontaktbestände oder Dateien können ein Upgrade oder zusätzliche Kapazität erfordern; ein aktives Vertriebsteam sollte außerdem Integrations- und Automationsbedarf prüfen.","alternatives":["Pipedrive","HubSpot Sales Hub."],"sources":[{"label":"Pakete und Grenzen","url":"https://centralstationcrm.de/plans"}],"vendorUrl":"https://centralstationcrm.de/plans","priceShort":"Starter kostenlos (bis 3 Nutzer, 200 Kontakte)"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'centralstationcrm','https://centralstationcrm.de/plans','direct',true where not exists (select 1 from public.outbound_links where product_slug='centralstationcrm' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('zoho-crm','crm','Zoho CRM','{"id":19,"name":"Zoho CRM","slug":"zoho-crm","category":"CRM","categorySlug":"crm","fit":"Unternehmen, die ein anpassbares CRM mit Workflows und breitem Funktionsausbau suchen.","pricing":"Kostenfreie Edition laut deutscher Herstellerseite für bis zu drei Benutzer. Für Standard, Professional, Enterprise und Ultimate liegt kein verifizierter deutscher Euro-Listenpreis vor; bitte ein Euro-Angebot für die benötigte Edition einholen.","features":"Standard unter anderem Pipeline, Workflow und Berichte; höhere Editionen erweitern Prozessautomatisierung, Anpassung und Analysen.","review":"Zoho eignet sich für Teams, die Prozessstruktur aktiv konfigurieren wollen. Die vielen Editionen und Sonderlizenzarten verlangen genaue Prüfung von Nutzerrollen und benötigten Funktionen. Eine INR-Zahl aus der DE-Seite darf nicht als deutscher Preis veröffentlicht werden.","alternatives":["HubSpot Sales Hub","Pipedrive."],"sources":[{"label":"Deutsche Editionen und Preiswähler","url":"https://www.zoho.com/de/crm/zohocrm-pricing.html"}],"vendorUrl":"https://www.zoho.com/de/crm/zohocrm-pricing.html","priceShort":"Kostenfreie Edition laut deutscher Herstellerseite für bis zu drei Benutzer"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'zoho-crm','https://www.zoho.com/de/crm/zohocrm-pricing.html','direct',true where not exists (select 1 from public.outbound_links where product_slug='zoho-crm' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('superoffice-crm','crm','SuperOffice CRM','{"id":20,"name":"SuperOffice CRM","slug":"superoffice-crm","category":"CRM","categorySlug":"crm","fit":"Mittelständische Teams, die Vertrieb, Service und Kundenkontakt auf einer CRM-Plattform bündeln möchten.","pricing":"Starter 45 €, Core 65 €, Growth 95 €, Plus 130 €, Super 160 € pro Nutzer und Monat; die Website sagt, dass die angezeigten Preise für jährliche Zahlung gelten.","features":"Kontakte und Aktivitäten ab Starter; Core ergänzt Pipeline, Projekte, Service und Automatisierung, Growth stärkere Vertriebs- und Serviceprozesse.","review":"Das Produkt ist als breites Kundenmanagement sinnvoll, wenn mehrere Abteilungen denselben Datenbestand brauchen. Der Preis pro Person und separat angebotene Einführung/Schulung sollten vor Vertragsabschluss als Gesamtkosten gerechnet werden.","alternatives":["HubSpot Sales Hub","Pipedrive."],"sources":[{"label":"Deutsche Preise und Leistungsgrenzen","url":"https://www.superoffice.de/preise/"}],"vendorUrl":"https://www.superoffice.de/preise/","priceShort":"Starter 45 €, Core 65 €, Growth 95 €, Plus 130 €, Super 160 € pro Nutzer und Monat"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'superoffice-crm','https://www.superoffice.de/preise/','direct',true where not exists (select 1 from public.outbound_links where product_slug='superoffice-crm' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('weclapp','erp','weclapp','{"id":21,"name":"weclapp","slug":"weclapp","category":"ERP","categorySlug":"erp","fit":"Kleine bis mittlere Dienstleister, Händler und E-Commerce-Teams.","pricing":"ERP Starter 39 €/Nutzer/Monat; Dienstleistung 86 € bei jährlicher bzw. 95 € bei monatlicher Zahlung; Handel 163/179 €; netto. Enterprise auf Anfrage.","features":"Starter für Kontakte, Angebote, Rechnungen und Fibu; Dienstleistung ergänzt CRM/Projekte/Zeit, Handel Warenwirtschaft, Lager und Produktion.","review":"Die Trennung nach Arbeitsmodell erleichtert die Vorauswahl. Der Starterpreis ist für Handelsunternehmen ungeeignet als Vergleichsanker, weil die relevanten Lager-/Shopfunktionen erst im Handelspaket liegen. Bei mehreren Mitarbeitenden wächst der Nutzerpreis spürbar.","alternatives":["Xentral für auftragsstarken Handel","Sage 100 für modulare Mittelstandsprozesse."],"sources":[{"label":"Pakete und Preise","url":"https://www.weclapp.com/de/preise/"}],"vendorUrl":"https://www.weclapp.com/de/preise/","priceShort":"ERP Starter 39 €/Nutzer/Monat"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'weclapp','https://www.weclapp.com/de/preise/','direct',true where not exists (select 1 from public.outbound_links where product_slug='weclapp' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('xentral','erp','Xentral','{"id":22,"name":"Xentral","slug":"xentral","category":"ERP","categorySlug":"erp","fit":"Handels- und E-Commerce-Unternehmen mit Aufträgen, Lager, Versand und Shop-/Marktplatzanbindung.","pricing":"Launch ab 99 €/Monat für Startups bis 500.000 € Jahresumsatz, plus 0,30 €/Auftrag laut Seite; Starter ab 349 €/Monat inklusive 500 Aufträgen/Monat und unbegrenzten Nutzern. Weitere Kosten hängen von Volumen, Modulen und Geschäftsmodell ab.","features":"Shop-/Marktplatz-Anbindung, Lager, Versand, Rechnungen, DATEV; Pakete unterscheiden sich nach Umfang und Volumen.","review":"Die unbegrenzten Nutzer können bei Teamwachstum attraktiv sein. Für die Kostenentscheidung sind Auftragsvolumen, Umsatzgrenze und Zusatzmodule wichtiger als ein bloßer Nutzervergleich. Dienstleistungsbetriebe ohne Warenfluss sollten Alternativen prüfen.","alternatives":["weclapp","Odoo."],"sources":[{"label":"Preise und Bedingungen","url":"https://xentral.com/de/preise"}],"vendorUrl":"https://xentral.com/de/preise","priceShort":"Launch ab 99 €/Monat für Startups bis 500"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'xentral','https://xentral.com/de/preise','direct',true where not exists (select 1 from public.outbound_links where product_slug='xentral' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('odoo','erp','Odoo','{"id":23,"name":"Odoo","slug":"odoo","category":"ERP","categorySlug":"erp","fit":"Unternehmen, die CRM, Buchhaltung, Lager, Verkauf und weitere Anwendungen auf einer modularen Plattform verbinden wollen.","pricing":"Eine App ist kostenlos nutzbar. Für Standard und Custom liegt kein verifizierter deutscher Euro-Listenpreis vor; Euro-Angebot einschließlich Nutzerzahl, Hosting und Einführung anfordern. Odoo.sh-Hosting kann gesondert kosten.","features":"Standard bietet Apps auf Odoo Online; Custom ergänzt Studio, mehrere Firmen, externe API und andere Hosting-Optionen.","review":"Die breite App-Auswahl macht Odoo für unterschiedliche Geschäftsmodelle interessant. Anpassungen, Implementierung und Partnerleistungen können das Gesamtbudget wesentlich verändern; für deutsche Buchhaltungsprozesse konkrete Lokalisierung vor Kauf prüfen.","alternatives":["weclapp","Business Central."],"sources":[{"label":"Tarife und Fußnoten","url":"https://www.odoo.com/de_DE/pricing"}],"vendorUrl":"https://www.odoo.com/de_DE/pricing","priceShort":"Eine App kostenlos; Euro-Angebot für Standard und Custom erforderlich"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'odoo','https://www.odoo.com/de_DE/pricing','direct',true where not exists (select 1 from public.outbound_links where product_slug='odoo' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('sage-100','erp','Sage 100','{"id":24,"name":"Sage 100","slug":"sage-100","category":"ERP","categorySlug":"erp","fit":"Mittelständische Betriebe aus Handel, Dienstleistung und Fertigung mit individuellen Abläufen in Warenwirtschaft, Rechnungswesen oder Produktion, die ein anpassbares ERP lokal oder in der Cloud betreiben möchten.","pricing":"Warenwirtschaft ab 56 €, Rechnungswesen ab 58 € und Produktion ab 90 € je Nutzer und Monat; das Produktionsmodul enthält das Warenwirtschaftspaket. Preise bei jährlicher Rechnungsstellung und zwölf Monaten Mindestlaufzeit, zzgl. MwSt.; andere Laufzeiten optional. Zusatzlösungen, Einführung und die Cloudvariante werden individuell angeboten.","features":"Warenwirtschaft mit Auftragsverwaltung, Bestellwesen, Kommissionierung, Lager und Inventur, Seriennummern und Chargen sowie Sanktionslistenprüfung. Rechnungswesen mit Finanz und Anlagenbuchhaltung, Kostenrechnung, Bilanzierung, Zahlungsverkehr, Mahnwesen, DATEV Austausch, Umsatzsteuervoranmeldung über ELSTER und über 40 Kennzahlen. Produktion mit Fertigungssteuerung, CAD Schnittstelle, Simulation, Vor und Nachkalkulation, Betriebsdatenerfassung und grafischer Ressourcenplanung. Alle Module mit unbegrenzter Mandantenzahl.","review":"Sage 100 ist ein klassisches, über Jahrzehnte gewachsenes ERP für den Mittelstand mit großem Partnerumfeld. Die öffentlichen Modulpreise sind für diese Klasse ungewöhnlich transparent, bilden aber nur die Lizenz ab. Den tatsächlichen Aufwand bestimmen Zusatzlösungen wie CRM, Dokumentenmanagement, Webshop oder Lohn sowie die Einführung durch einen Fachhändler. Stark ist Sage 100 bei mehreren Mandanten, Währungen und hohem Belegaufkommen. Wer eine sofort nutzbare Cloudsoftware mit monatlicher Kündigung sucht, ist hier falsch.","alternatives":["weclapp für einen cloudbasierten Einstieg","Business Central für Unternehmen mit Microsoft Umgebung"],"sources":[{"label":"Module, Preise, Vertragsbedingungen und FAQ","url":"https://www.sage.com/de-de/produkte/sage-100/"}],"vendorUrl":"https://www.sage.com/de-de/produkte/sage-100/","priceShort":"ab 56 € je Nutzer und Monat, Modulpreis"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'sage-100','https://www.sage.com/de-de/produkte/sage-100/','direct',true where not exists (select 1 from public.outbound_links where product_slug='sage-100' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('microsoft-dynamics-365-business-central','erp','Microsoft Dynamics 365 Business Central','{"id":25,"name":"Microsoft Dynamics 365 Business Central","slug":"microsoft-dynamics-365-business-central","category":"ERP","categorySlug":"erp","fit":"Wachsende mittelständische Unternehmen, besonders mit Microsoft-Umgebung und Bedarf an Finanz-, Vertriebs- und Warenprozessen.","pricing":"Essentials 69,30 €, Premium 95,30 €, Team Members 6,90 € pro Nutzer und Monat bei jährlicher Abrechnung, zzgl. MwSt.; Microsoft warnt vor regionalen Abweichungen und verweist für Kauf/Beratung an Partner.","features":"Essentials mit Finanzmanagement, Einkauf, Lager und Projekten; Premium ergänzt Dienstverwaltung und Fertigung.","review":"Der Funktionsumfang spricht für komplexere Abläufe. Für einen realistischen Vergleich müssen Partnerimplementierung, Anpassungen, Apps und unterschiedliche Lizenztypen zusätzlich zum Listenpreis kalkuliert werden.","alternatives":["Sage 100","Odoo."],"sources":[{"label":"Deutsche Preise und Leistungsübersicht","url":"https://www.microsoft.com/de-de/dynamics-365/products/business-central/pricing"}],"vendorUrl":"https://www.microsoft.com/de-de/dynamics-365/products/business-central/pricing","priceShort":"Essentials 69,30 €, Premium 95,30 €, Team Members 6,90 € pro Nutzer und Monat bei jährlicher Abrechnung, "}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'microsoft-dynamics-365-business-central','https://www.microsoft.com/de-de/dynamics-365/products/business-central/pricing','direct',true where not exists (select 1 from public.outbound_links where product_slug='microsoft-dynamics-365-business-central' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('sage-hr','hr','Sage HR','{"id":26,"name":"Sage HR","slug":"sage-hr","category":"Personal","categorySlug":"hr","fit":"Kleine und mittlere Unternehmen, die Abwesenheiten, Personalakten und Selbstbedienung für Beschäftigte digitalisieren und Zeiterfassung, Schichtplanung, Spesen oder Recruiting nur bei Bedarf hinzubuchen möchten.","pricing":"Basis 4,50 € je Beschäftigtem und Monat, zzgl. MwSt. Zubuchbar sind Arbeitszeittabellen, Performance und Schichtplanung für je 2,50 €, Ausgaben für 1,50 € je Person und Monat sowie Recruiting pauschal für 175 € pro Monat. Die Beispielpakete kosten 7,00 € (Basis mit Zeit) und 9,50 € (Basis mit Zeit und Schichten). Kündigung mit einem Monat Frist, Test über 30 Tage ohne Zahlungsdaten.","features":"Basis mit Abwesenheitsmanagement, digitaler Mitarbeiterakte, interaktivem Organigramm, Selbstbedienung und mobiler App. Zeitmodul mit projektbezogenen Arbeitszeittabellen, Arbeitsmustern und Freigaben; Schichtmodul mit Vertretungen und Regeln zur Arbeitszeit; Performance mit Zielen, Feedback und anonymen Umfragen; Ausgaben mit Belegfoto; Recruiting mit Stellenseiten, Bewerberpipeline und Outlook Kalender. Eine Lohnabrechnung ist nicht enthalten.","review":"Sage HR überzeugt durch ein sehr transparentes Baukastenmodell: Jedes Modul hat einen öffentlichen Preis je Person, sodass sich die Kosten vor dem ersten Gespräch genau berechnen lassen. Das ist im Personalmarkt keineswegs selbstverständlich. Die Kehrseite zeigt sich bei wachsender Belegschaft, weil jedes Modul mit jeder Person multipliziert wird. Recruiting kostet pauschal 175 € im Monat und lohnt sich eher bei regelmäßigen Einstellungen. Wer zusätzlich die Lohnabrechnung braucht, sollte Sage HR & Payroll gegenrechnen, denn dort sind viele Module bereits enthalten.","alternatives":["Factorial für modulare Personalprozesse","Kenjo für operative Teams mit Schichtbetrieb"],"sources":[{"label":"Modulpreise, Beispielpakete und FAQ","url":"https://www.sage.com/de-de/sage-business-cloud/hr/"}],"vendorUrl":"https://www.sage.com/de-de/sage-business-cloud/hr/","priceShort":"ab 4,50 € je Beschäftigtem und Monat"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'sage-hr','https://www.sage.com/de-de/sage-business-cloud/hr/','direct',true where not exists (select 1 from public.outbound_links where product_slug='sage-hr' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('sage-hr-payroll','lohnabrechnung','Sage HR & Payroll','{"id":27,"name":"Sage HR & Payroll","slug":"sage-hr-payroll","category":"Lohnabrechnung","categorySlug":"lohnabrechnung","fit":"Mittelständische Betriebe, laut Hersteller besonders ab etwa 50 Beschäftigten, die Personalprozesse von der Bewerbung bis zur Entgeltabrechnung aus einer Hand steuern möchten.","pricing":"Essentials 40 €, Standard 60 € und Premium 80 € pro Monat, jeweils für 5 Beschäftigte und zzgl. 19 % MwSt. Weitere Beschäftigte kosten ab 7 €, ab 9 € beziehungsweise ab 11 € pro Person und Monat. Laut Hersteller jederzeit kündbar. Einen Test über 30 Tage gibt es direkt nur für Essentials; Standard und Premium werden über eine Webdemo angeboten.","features":"Essentials: Portal für das Onboarding, Arbeitszeittabellen und Überstunden, Organigramm, Genehmigungsabläufe, alle Urlaubs und Abwesenheitsarten, Schichtplanung, Spesen per App, automatische Lohnabrechnung mit Meldungen, mobile App, Rechteverwaltung, Export für Sage und DATEV. Standard ergänzt Lohnabrechnung für komplexere Fälle mit Sonderlöhnen, Mehrmandantenfähigkeit, Controlling und Korrespondenz mit Behörden. Premium bringt Korrektursimulation, automatisierte Korrektur und Abrechnungsläufe, Projektzeiterfassung, Performance mit OKR, 360 Grad Feedback und Befragungen sowie Recruiting mit Bewerberpipeline.","review":"Sage HR & Payroll ist das breiteste Cloudpaket von Sage für Personal und Lohn. Bemerkenswert ist, wie viel bereits in Essentials steckt: Schichtplanung, Arbeitszeiten und Spesen sind enthalten, die bei Sage HR einzeln berechnet würden. Die wichtige Grenze liegt bei der Lohnabrechnung. Essentials rechnet in der Cloud ab und schließt Baulohn, öffentlichen Dienst und Versorgungsbezüge aus. Standard und Premium beruhen laut Hersteller auf einer Desktop Lohnabrechnung mit erweiterten Funktionen. Wer eine reine Cloudumgebung erwartet, sollte diese Architektur vor Vertragsschluss genau erklären lassen.","alternatives":["Sage Payroll für eine schlankere Lohnlösung mit weniger Personalfunktionen","Personio Payroll für Betriebe, die Personio als Personalsystem nutzen"],"sources":[{"label":"Pakete, Preise, Ausschlüsse und FAQ","url":"https://www.sage.com/de-de/produkte/sage-hr-payroll/"}],"vendorUrl":"https://www.sage.com/de-de/produkte/sage-hr-payroll/","priceShort":"ab 40 € pro Monat für 5 Beschäftigte"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'sage-hr-payroll','https://www.sage.com/de-de/produkte/sage-hr-payroll/','direct',true where not exists (select 1 from public.outbound_links where product_slug='sage-hr-payroll' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('sage-50-handwerk','erp','Sage 50 Handwerk','{"id":28,"name":"Sage 50 Handwerk","slug":"sage-50-handwerk","category":"ERP","categorySlug":"erp","fit":"Handwerksbetriebe aller Gewerke mit Angeboten, Aufträgen, Aufmaß, Material und Monteurplanung, die eine installierte kaufmännische Software mit Handwerksschnittstellen suchen.","pricing":"Essential 19,90 € pro Monat für einen Benutzer, Enterprise 59 € pro Monat für unbegrenzte Benutzer; jeweils zzgl. MwSt. bei jährlicher Rechnungsstellung und zwölf Monaten Mindestlaufzeit. Kürzere oder längere Laufzeiten sind laut Hersteller optional. Schnittstellen, Dokumentenmanagement, Finanzbuchhaltung und das Cloud Paket werden zusätzlich berechnet; Preise dafür nennt Sage nicht öffentlich.","features":"Essential: Angebote, Aufträge und Rechnungen, elektronische Rechnungen im Format ZUGFeRD 2.1 und XRechnung, Stammdaten, Projektverwaltung, Express Auftrag und SmartFinder. Enterprise ergänzt Teil und Schlussrechnungen sowie den Terminkalender. Optional: GAEB, IDS und OCI für den Großhandel, DATANORM, Nachkalkulation, Wartung und Service, Regiezentrum, Termin und Ressourcenplanung, Lager und Bestellwesen, mobile Zeiterfassung und das Cloud Paket mit mobiler Projektmappe.","review":"Sage 50 Handwerk ist eine gewachsene Branchenlösung, die typische Abläufe vom Aufmaß bis zur Schlussrechnung kennt. Der günstige Einstieg täuscht allerdings leicht: Essential umfasst nur einen Benutzer und laut Paketübersicht keine Teil und Schlussrechnungen. Genau diese Rechnungsarten brauchen viele Bau und Ausbaubetriebe, sodass Enterprise der realistische Vergleichspreis ist. Die Software wird lokal installiert und über Fachhandelspartner vertrieben. Mobiles Arbeiten und Dokumentenmanagement kommen über ein zusätzliches Cloud Paket.","alternatives":["Sage 100 für breitere Mittelstandsprozesse","weclapp für cloudbasierte Auftrags und Warenprozesse"],"sources":[{"label":"Funktionen, Pakete, Bedingungen und FAQ","url":"https://www.sage.com/de-de/produkte/sage-50-handwerk/"}],"vendorUrl":"https://www.sage.com/de-de/produkte/sage-50-handwerk/","priceShort":"ab 19,90 € pro Monat bei Jahresrechnung"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'sage-50-handwerk','https://www.sage.com/de-de/produkte/sage-50-handwerk/','direct',true where not exists (select 1 from public.outbound_links where product_slug='sage-50-handwerk' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('sage-intacct','erp','Sage Intacct','{"id":29,"name":"Sage Intacct","slug":"sage-intacct","category":"ERP","categorySlug":"erp","fit":"Wachsende Unternehmen und Unternehmensgruppen mit eigener Finanzabteilung, die Buchhaltung, Konsolidierung, Berichtswesen und Automatisierung in einer Cloudplattform zusammenführen möchten.","pricing":"Standard ab 1.390 € pro Monat netto zzgl. MwSt. als Richtpreis, inklusive zwei Business Usern. Zusatzmodule haben veröffentlichte Richtpreise, zum Beispiel weitere Business User 240 €, Bankanbindung 160 €, Multiwährung 585 €, mehrere Gesellschaften 215 € plus 60 € je Gesellschaft und globale Konsolidierung 1.005 € pro Monat. Einführung, Migration und Schulung werden separat angeboten.","features":"Im Standard enthalten: Hauptbuch, Debitoren und Kreditoren, elektronische Rechnungen, Zahlungsverkehr und Cash Management, Verkauf und Einkauf, eine Steuerlösung, nationale Konsolidierung, Berichte und Dashboards, Sage Copilot mit Anomalieerkennung, Backups und unbegrenzter Speicher. Zubuchbar: Automatisierung von Rechnungseingang und Abschluss, Anlagenbuchhaltung, dynamische Zuweisungen, Umsatzrealisierung, Projektmodule, interaktive Berichte und API Zugang.","review":"Sage Intacct ist für Finanzteams gebaut, die über eine klassische Buchhaltung hinausgewachsen sind. Sage legt die Richtpreise einzelner Module offen, was die Budgetplanung deutlich erleichtert. Der Einstiegspreis enthält jedoch nur zwei Vollnutzer, und typische Anforderungen wie Bankanbindung, Multiwährung oder mehrere Gesellschaften kosten jeweils extra. Für eine realistische Kalkulation sollten Sie deshalb Module, Nutzerrollen und Einführung zusammen betrachten. Für kleine Betriebe mit einer einzigen Gesellschaft ist die Plattform in der Regel überdimensioniert.","alternatives":["Business Central für Microsoft Umgebungen","Sage 100 für modulare Waren und Finanzprozesse"],"sources":[{"label":"Deutsche Preisübersicht mit Modulpreisen und FAQ","url":"https://www.sage.com/de-de/sage-business-cloud/intacct/pricing/"}],"vendorUrl":"https://www.sage.com/de-de/sage-business-cloud/intacct/pricing/","priceShort":"ab 1.390 € pro Monat netto"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'sage-intacct','https://www.sage.com/de-de/sage-business-cloud/intacct/pricing/','direct',true where not exists (select 1 from public.outbound_links where product_slug='sage-intacct' and active);
insert into public.catalog_products (slug,category_slug,name,profile,verified_at) values ('sage-sales-management','crm','Sage Sales Management','{"id":30,"name":"Sage Sales Management","slug":"sage-sales-management","category":"CRM","categorySlug":"crm","fit":"Vertriebsteams mit Außendienst und Geschäftskunden ab fünf Personen, die Besuche, Kontakte und Verkaufschancen mobil und auch offline dokumentieren und die Pipeline zentral steuern möchten.","pricing":"Professional 55 € je Nutzer und Monat bei mindestens fünf Nutzern, also ab 275 € pro Monat. Zubuchbar sind Angebote und Bestellungen für 7 €, Vertriebskampagnen für 10 € sowie weitere Sprachberichte für 10 € je Nutzer und Monat; zusätzliche Signaturen ab 30 € pro Monat. Einen Steuerhinweis nennt die Preisangabe nicht.","features":"Accounts, Kontakte und Verkaufschancen bis je 100.000 Datensätze, Kalender und Aufgaben, Aktivitätsverfolgung, geolokalisierte Verkaufschancen, Routenplanung, Offline Nutzung und Apps für iOS und Android. Sage Copilot fasst E-Mails zusammen, erstellt Termine per Sprache und scannt Visitenkarten; 150 Sprachberichte sind enthalten. Dazu kommen Ziele, Mitteilungen, eigene Felder, Mehrwährung, Integration von Microsoft 365, Google Workspace, Zoom, Mailchimp, Zendesk, Zapier und Make sowie eine API.","review":"Sage Sales Management ist kein allgemeines CRM, sondern eine konsequent mobile Lösung für den Außendienst. Sprachberichte, Visitenkartenscanner und Offline Nutzung sind genau auf Vertriebsmitarbeitende zugeschnitten, die viel unterwegs sind. Die Mindestabnahme von fünf Lizenzen macht den Einstieg mit 275 € pro Monat vergleichsweise teuer. Angebote aus dem CRM heraus kosten zusätzlich. Eine native Anbindung beschreibt Sage vor allem für ERP Produkte anderer Länder; für deutsche Systeme wie Sage 100 sollten Sie den Integrationsweg konkret prüfen.","alternatives":["Pipedrive für eine fokussierte Pipeline ohne Mindestnutzerzahl","SuperOffice CRM für abteilungsübergreifende Kundenprozesse"],"sources":[{"label":"Professional Paket, Funktionen und Zusatzmodule","url":"https://www.sage.com/de-de/produkte/sage-sales-management/"}],"vendorUrl":"https://www.sage.com/de-de/produkte/sage-sales-management/","priceShort":"55 € je Nutzer und Monat, mindestens fünf Nutzer"}'::jsonb,'2026-09-25T00:00:00Z') on conflict (slug) do update set category_slug=excluded.category_slug,name=excluded.name,profile=excluded.profile,verified_at=excluded.verified_at,updated_at=now();
insert into public.outbound_links (product_slug,destination_url,link_type,active) select 'sage-sales-management','https://www.sage.com/de-de/produkte/sage-sales-management/','direct',true where not exists (select 1 from public.outbound_links where product_slug='sage-sales-management' and active);
